const DEFAULT_PREPARATION = items('症状开始时间和变化趋势|体温、饮水进食、尿便和精神记录|已经使用的药物或处理|接触史、基础疾病和既往检查', 'Symptom onset and trend|Temperature, intake, output and alertness records|Medicines or care already used|Contacts, underlying conditions and previous tests')

function defaultDisplayUnit(input) {
  const preciseSkinTopics = new Set(['atopic-dermatitis', 'diaper-dermatitis', 'contact-dermatitis', 'heat-rash', 'impetigo', 'fungal-skin-infection'])
  const skinResource = ANATOMY_RESOURCES.find((resource) => resource.id === 'skin')
  const resourceIds = new Set(ANATOMY_RESOURCES.map((resource) => resource.id))
  const organId = input.tags?.find((tag) => resourceIds.has(tag))
  const organResource = ANATOMY_RESOURCES.find((resource) => resource.id === organId)
  const hasSkinModel = preciseSkinTopics.has(input.id) && skinResource?.model
  const modelResource = hasSkinModel ? skinResource : organResource
  const hasModel = Boolean(modelResource?.model)
  return {
    id: `${input.id}-overview`,
    title: input.location,
    anchorIds: hasSkinModel ? ['epidermis'] : [],
    viewType: input.viewType || 'OVERVIEW',
    description: input.mechanism,
    displayOrder: 1,
    modelRef: hasModel ? modelResource.model : null,
    modelAvailability: hasModel ? 'AVAILABLE' : 'PLANNED',
    leaderLines: hasSkinModel ? [{ anchorId: 'epidermis', label: input.location, effect: input.mechanism }] : [],
  }
}

function specialDisplayUnits(input) {
  const skinResource = ANATOMY_RESOURCES.find((resource) => resource.id === 'skin')
  const liverResource = ANATOMY_RESOURCES.find((resource) => resource.id === 'liver')
  if (input.id === 'hand-foot-mouth') return [
    ['mouth', t('口腔黏膜', 'Oral mucosa')],
    ['palm', t('手掌', 'Palms')],
    ['sole', t('足底', 'Soles')],
  ].map(([id, title], index) => ({
    id: `hand-foot-mouth-${id}`,
    title,
    anchorIds: [],
    viewType: 'SURFACE_MAP',
    description: input.mechanism,
    displayOrder: index + 1,
    modelRef: id === 'mouth' ? null : skinResource?.model || null,
    modelAvailability: id === 'mouth' || !skinResource?.model ? 'PLANNED' : 'AVAILABLE',
    leaderLines: [],
  }))
  if (input.id === 'newborn-jaundice') return [
    { id: 'newborn-jaundice-surface', title: t('皮肤与巩膜黄染', 'Yellow skin and sclera'), anchorIds: [], viewType: 'SURFACE_MAP', description: t('这是家长可观察的表现层，不代表病因位于皮肤。', 'This is the visible layer and does not mean the cause is in the skin.'), displayOrder: 1, modelRef: skinResource?.model || null, modelAvailability: skinResource?.model ? 'AVAILABLE' : 'PLANNED', leaderLines: [] },
    { id: 'newborn-jaundice-pathway', title: t('胆红素产生、肝脏处理与排泄', 'Bilirubin production, liver processing and excretion'), anchorIds: [], viewType: 'PATHWAY', description: input.mechanism, displayOrder: 2, modelRef: liverResource?.model || null, modelAvailability: liverResource?.model ? 'AVAILABLE' : 'PLANNED', leaderLines: [] },
  ]
  return null
}

function defineDisease(input) {
  const profile = PROFILES[input.profile]
  const symptoms = items(input.symptoms[0], input.symptoms[1])
  const displayUnits = input.displayUnits || specialDisplayUnits(input) || [defaultDisplayUnit(input)]
  return Object.freeze({
    id: input.id,
    name: input.name,
    aliases: items(input.aliases?.[0] || '', input.aliases?.[1] || '').filter((item) => item.zh),
    ageRange: { minDays: input.age[0], maxDays: input.age[1], label: input.age[2] },
    category: CATEGORIES[input.profile],
    categoryTags: input.tags || [input.profile],
    shortDefinition: input.definition,
    quickTake: {
      location: input.location,
      mechanism: input.mechanism,
      typicalSigns: symptoms.slice(0, 3),
      course: input.course,
      watch: profile.observation[0],
      department: input.department,
    },
    anatomyBinding: {
      diseaseId: input.id,
      anatomyAnchors: displayUnits.flatMap((unit) => unit.anchorIds),
      primaryAnchor: displayUnits[0]?.anchorIds[0] || null,
      locationType: input.locationType || 'FOCAL',
      displayUnits,
      modelAvailability: displayUnits.some((unit) => unit.modelAvailability === 'AVAILABLE') ? 'AVAILABLE' : 'PLANNED',
    },
    causes: [input.cause],
    triggers: input.triggers || [],
    riskFactors: input.riskFactors || [],
    transmission: input.transmission || null,
    mechanismSteps: [t('正常结构与功能', 'Normal structure and function'), input.cause, input.mechanism, symptoms[0]],
    impacts: input.impacts || symptoms.slice(0, 3),
    commonSymptoms: symptoms,
    diseaseCourse: input.course,
    observationGuidance: profile.observation,
    generalManagement: profile.management,
    homeCareGuidance: profile.homeCare,
    avoidActions: profile.avoid,
    careDepartment: { primary: input.department, fallback: t('儿科；紧急情况进入儿童急诊或急诊', 'Pediatrics; use pediatric emergency or emergency care when urgent') },
    carePreparation: DEFAULT_PREPARATION,
    prevention: profile.prevention,
    escalationRuleRef: input.escalationRuleRef || 'decision-unit:general_health_preassessment',
    sourceRefs: (input.sourceIds || ['aapCommon']).map((id) => DISEASE_SOURCES[id]),
    status: 'PUBLISHED',
    version: DISEASE_CONTENT_VERSION,
    review: { status: 'SOURCE_CHECKED', lastReviewedAt: '2026-08-08', knownLimitations: t('通用家庭教育内容，不用于诊断、分级或个体化处方。', 'General family education only; not for diagnosis, triage or individualized prescriptions.') },
  })
}

