export const ORGAN_TOPICS = Object.freeze([
  ...ANATOMY_RESOURCES.map((resource) => ({
    ...ORGAN_COPY[resource.id],
    id: resource.id,
    name: resource.title,
    system: resource.system,
    shortFunction: t('通过儿童解剖模型认识结构、位置和基础功能。', 'Use a pediatric anatomy model to learn structure, location and basic function.'),
    childSpecificNotes: [ORGAN_COPY[resource.id]?.child || t('儿童结构和生理仍在发育。', 'Children\'s structure and physiology are still developing.'), t('模型用于教学，不用于诊断。', 'The model teaches anatomy and does not diagnose.')],
    anatomyAnchors: [],
    modelAvailability: resource.model ? 'AVAILABLE' : 'PLANNED',
    modelRef: resource.model || null,
    relatedDiseaseIds: DISEASE_TOPICS.filter((topic) => topic.categoryTags.includes(resource.id)).map((topic) => topic.id),
  })),
  ...PLANNED_ORGANS.map((organ) => ({
    ...organ,
    ...ORGAN_COPY[organ.id],
    shortFunction: t('认识该结构的基本功能，以及儿童阶段常见疾病发生在哪里。', 'Learn the structure\'s basic function and where common childhood illnesses occur.'),
    childSpecificNotes: [ORGAN_COPY[organ.id]?.child || t('儿童结构和生理仍在发育。', 'Children\'s structure and physiology are still developing.'), t('没有模型时文字指导仍完整可用。', 'Text guidance remains available without a model.')],
    anatomyAnchors: [],
    modelAvailability: 'PLANNED',
    modelRef: null,
    relatedDiseaseIds: DISEASE_TOPICS.filter((topic) => topic.categoryTags.includes(organ.id)).map((topic) => topic.id),
  })),
])

export function getDiseaseTopic(id) {
  return DISEASE_TOPICS.find((topic) => topic.id === id) || DISEASE_TOPICS[0]
}

export function searchDiseaseTopics(query = '', locale = 'zh-CN') {
  const needle = String(query).trim().toLocaleLowerCase()
  if (!needle) return DISEASE_TOPICS
  const language = locale === 'en-US' ? 'en' : 'zh'
  return DISEASE_TOPICS.filter((topic) => [topic.name, topic.category, topic.shortDefinition, ...topic.aliases]
    .some((value) => String(value?.[language] || value?.zh || '').toLocaleLowerCase().includes(needle)))
}

export function diseasesForOrgan(organId) {
  return DISEASE_TOPICS.filter((topic) => topic.anatomyBinding.displayUnits.some((unit) => unit.modelRef?.includes(organId)) || topic.categoryTags.includes(organId))
}
